 "content": "def transform(grid):
    """Extend each corner marker's outward diagonal from a 2x2 block.

    The four marker colors rotate clockwise onto the outward diagonals:
    NW <- SW, NE <- NW, SE <- NE, SW <- SE.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2
                   for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))

    for r, c in blocks:
        corners = {
            "NW": (r - 1, c - 1),
            "NE": (r - 1, c + 2),
            "SW": (r + 2, c - 1),
            "SE": (r + 2, c + 2),
        }
        # Preserve the original corner colors as the source for the rotation.
        values = {name: grid[rr][cc] for name, (rr, cc) in corners.items()
                  if 0 <= rr < h and 0 <= cc < w}
        rotations = {"NW": "SW", "NE": "NW", "SW": "SE", "SE": "NE"}
        directions = {"NW": (-1, -1), "NE": (-1, 1),
                      "SW": (1, -1), "SE": (1, 1)}
        for name, (rr, cc) in corners.items():
            if not (0 <= rr < h and 0 <= cc < w):
                continue
            source = rotations[name]
            if source not in values:
                continue
            color = values[source]
            dr, dc = directions[name]
            y, x = rr, cc
            while 0 <= y < h and 0 <= x < w:
                out[y][x] = color
                y += dr
                x += dc

    return out
