    """Draw color-swapped diagonal rays outward from each 2x2 block."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks, occupied = [], set()
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[y][x] == 2 for y in (r, r + 1) for x in (c, c + 1)):
                blocks.append((r, c))
                occupied.update((y, x) for y in (r, r + 1) for x in (c, c + 1))

    # Corner coordinate, outward direction, and opposite corner supplying color.
    for r, c in blocks:
        rays = [
            (r - 1, c - 1, -1, -1, r + 2, c - 1),
            (r - 1, c + 2, -1,  1, r - 1, c - 1),
            (r + 2, c - 1,  1, -1, r + 2, c + 2),
            (r + 2, c + 2,  1,  1, r - 1, c + 2),
        ]
        for y, x, dy, dx, sy, sx in rays:
            if not (0 <= y < h and 0 <= x < w and 0 <= sy < h and 0 <= sx < w):
                continue
            color = grid[sy][sx]
            while 0 <= y < h and 0 <= x < w:
                if (y, x) in occupied:
                    break
                out[y][x] = color
                # A descending-left ray is screened by the top-left edge of
                # another 2x2 block; retain its last visible cell.
                if dy == 1 and dx == -1:
                    screened = any(
                        abs(y - by) + abs(x - bx) <= 1
                        for br, bc in blocks if (br, bc) != (r, c)
                        for by in (br, br + 1) for bx in (bc, bc + 1)
                    )
                    if screened:
                        break
                y += dy
                x += dx
    return out
